<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requireLogin();$pageTitle='نتایج ارزیابی';$user=Auth::user();
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/survey-results.php');}$surveyId=(int)$_POST['survey_id'];$allowed=Auth::isAdmin()||Database::fetch('SELECT id FROM survey_assignments WHERE survey_id=? AND user_id=?',[$surveyId,$user['id']]);if(!$allowed){flash('دسترسی غیرمجاز.','danger');redirect('/admin/survey-results.php');}$kpis=Database::fetchAll('SELECT sk.kpi_id,sk.weight FROM survey_kpis sk WHERE sk.survey_id=?',[$surveyId]);$sumW=0;$sum=0;foreach($kpis as $k){$score=max(0,min(100,(float)($_POST['score'][$k['kpi_id']]??0)));$sumW+=(float)$k['weight'];$sum+=$score*(float)$k['weight'];}$final=$sumW>0?$sum/$sumW:0;$pdo=Database::connection();$pdo->beginTransaction();try{Database::execute('INSERT INTO survey_results (survey_id,user_id,employee_name,final_score,created_at,updated_at) VALUES (?,?,?,?,NOW(),NOW())',[$surveyId,$user['id'],$_POST['employee_name']?:$user['name'],$final]);$rid=(int)Database::lastInsertId();foreach($kpis as $k){$score=max(0,min(100,(float)($_POST['score'][$k['kpi_id']]??0)));Database::execute('INSERT INTO survey_result_items (result_id,kpi_id,score,weighted_score,created_at) VALUES (?,?,?,?,NOW())',[$rid,$k['kpi_id'],$score,$score*(float)$k['weight']]);}Database::execute('UPDATE survey_assignments SET status="completed" WHERE survey_id=? AND user_id=?',[$surveyId,$user['id']]);$pdo->commit();flash('نتیجه ثبت شد.');}catch(Throwable $e){$pdo->rollBack();flash('خطا در ثبت نتیجه.','danger');}redirect('/admin/survey-results.php');}
$assigned=Auth::isAdmin()?Database::fetchAll('SELECT * FROM surveys WHERE status="active" ORDER BY id DESC'):Database::fetchAll('SELECT s.* FROM surveys s JOIN survey_assignments sa ON sa.survey_id=s.id WHERE sa.user_id=? AND s.status="active" ORDER BY s.id DESC',[$user['id']]);
$sql='SELECT r.*,s.title survey_title,u.name user_name FROM survey_results r JOIN surveys s ON s.id=r.survey_id JOIN users u ON u.id=r.user_id '.(Auth::isAdmin()?'':'WHERE r.user_id=? OR EXISTS(SELECT 1 FROM survey_assignments sa WHERE sa.survey_id=r.survey_id AND sa.user_id=?)').' ORDER BY r.id DESC';$params=Auth::isAdmin()?[]:[$user['id'],$user['id']];$results=Database::fetchAll($sql,$params);require __DIR__.'/../views/partials/admin-header.php';?>
<div class="card admin-form"><h2>ثبت ارزیابی جدید</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><label class="form-field"><span>نظرسنجی</span><select name="survey_id" id="surveySelect" required><option value="">انتخاب کنید</option><?php foreach($assigned as $s):?><option value="<?=$s['id']?>"><?=e($s['title'])?></option><?php endforeach;?></select></label><label class="form-field"><span>نام کارمند/فرد ارزیابی‌شونده</span><input name="employee_name" value="<?=e($user['name'])?>" required></label><?php foreach($assigned as $s): $ks=Database::fetchAll('SELECT k.id,k.title,sk.weight FROM survey_kpis sk JOIN kpis k ON k.id=sk.kpi_id WHERE sk.survey_id=?',[$s['id']]);?><div class="survey-kpis" data-survey="<?=$s['id']?>" style="display:none"><h3><?=e($s['title'])?></h3><?php foreach($ks as $k):?><label class="form-field"><span><?=e($k['title'])?> - وزن <?=e($k['weight'])?></span><input type="number" min="0" max="100" step="0.01" name="score[<?=$k['id']?>]" value="0"></label><?php endforeach;?></div><?php endforeach;?><button class="btn btn-primary">ثبت نتیجه</button></form></div>
<h2 class="section-title">نتایج ثبت‌شده</h2><?php foreach($results as $r): $items=Database::fetchAll('SELECT i.*,k.title,k.weight FROM survey_result_items i JOIN kpis k ON k.id=i.kpi_id WHERE i.result_id=?',[$r['id']]);?><div class="card admin-form"><h3><?=e($r['employee_name'])?> - <?=e($r['survey_title'])?></h3><p class="muted">ثبت‌کننده: <?=e($r['user_name'])?> | امتیاز نهایی: <?=number_format($r['final_score'],2)?></p><div class="progress"><span style="width:<?=min(100,(float)$r['final_score'])?>%"></span></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>KPI</th><th>امتیاز</th><th>وزن</th><th>امتیاز وزنی</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['title'])?></td><td><?=e($it['score'])?></td><td><?=e($it['weight'])?></td><td><?=e($it['weighted_score'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php endforeach;?><script>document.getElementById('surveySelect')?.addEventListener('change',e=>{document.querySelectorAll('.survey-kpis').forEach(x=>x.style.display=x.dataset.survey===e.target.value?'block':'none')});</script></section></main></div><script src="/assets/js/app.js"></script></body></html>
